--
-- Name: v_concept_mastery; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_concept_mastery WITH (security_invoker='true') AS
 SELECT u.course_id,
    u.unit_number,
    t.id AS topic_id,
    t.title AS topic_title,
    c.id AS concept_id,
    c.name AS concept_name,
    c.difficulty,
    c.importance,
    c.concept_type,
    COALESCE(ps.assessments_count, (0)::bigint) AS assessments_count,
    ps.avg_score,
    ps.latest_score,
    ps.previous_score,
    (ps.latest_score - ps.previous_score) AS score_trend,
    ds.downstream_count,
        CASE
            WHEN (ps.avg_score IS NULL) THEN 'not_assessed'::text
            WHEN (((ps.avg_score)::double precision < COALESCE(tc.revision_threshold_score, (60.0)::double precision)) AND (ds.downstream_count >= 2)) THEN 'bottleneck'::text
            WHEN ((ps.avg_score)::double precision < COALESCE(tc.revision_threshold_score, (60.0)::double precision)) THEN 'weak'::text
            WHEN (ps.avg_score < 70.0) THEN 'moderate'::text
            ELSE 'strong'::text
        END AS mastery_status
   FROM (((((public.concepts c
     JOIN public.topics t ON (((t.id)::text = (c.topic_id)::text)))
     JOIN public.units u ON (((u.id)::text = (t.unit_id)::text)))
     LEFT JOIN public.teacher_constraints tc ON (((tc.course_id)::text = (u.course_id)::text)))
     LEFT JOIN LATERAL ( SELECT count(*) AS assessments_count,
            round((avg(p.average_score))::numeric, 1) AS avg_score,
            (array_agg(p.average_score ORDER BY p.recorded_at DESC))[1] AS latest_score,
            (array_agg(p.average_score ORDER BY p.recorded_at DESC))[2] AS previous_score
           FROM public.performance p
          WHERE ((p.concept_id)::text = (c.id)::text)
         HAVING (count(*) > 0)) ps ON (true))
     LEFT JOIN LATERAL ( WITH RECURSIVE downstream(cid) AS (
                 SELECT p.concept_id
                   FROM public.prerequisites p
                  WHERE ((p.prerequisite_id)::text = (c.id)::text)
                UNION
                 SELECT p.concept_id
                   FROM (public.prerequisites p
                     JOIN downstream d ON (((p.prerequisite_id)::text = (d.cid)::text)))
                )
         SELECT count(*) AS downstream_count
           FROM downstream) ds ON (true));

--
-- Name: v_course_progress; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_course_progress WITH (security_invoker='true') AS
 SELECT c.id AS course_id,
    c.code,
    c.title,
    c.total_classes,
    c.total_available_minutes,
    tp.total_topics,
    tp.completed_topics,
    tp.in_progress_topics,
    round(((100.0 * (tp.completed_topics)::numeric) / (NULLIF(tp.total_topics, 0))::numeric), 1) AS topic_completion_pct,
    sp.completed_sessions,
    sp.scheduled_sessions,
    sp.cancelled_sessions,
    round(((100.0 * (sp.completed_sessions)::numeric) / (c.total_classes)::numeric), 1) AS session_completion_pct,
    COALESCE(tm.taught_minutes, (0)::bigint) AS taught_minutes,
    (c.total_available_minutes - COALESCE(tm.taught_minutes, (0)::bigint)) AS remaining_minutes
   FROM (((public.courses c
     LEFT JOIN LATERAL ( SELECT count(*) AS total_topics,
            count(*) FILTER (WHERE ((t.status)::text = 'completed'::text)) AS completed_topics,
            count(*) FILTER (WHERE ((t.status)::text = 'in_progress'::text)) AS in_progress_topics
           FROM (public.topics t
             JOIN public.units u ON (((u.id)::text = (t.unit_id)::text)))
          WHERE ((u.course_id)::text = (c.id)::text)) tp ON (true))
     LEFT JOIN LATERAL ( SELECT count(*) FILTER (WHERE ((cs.status)::text = 'completed'::text)) AS completed_sessions,
            count(*) FILTER (WHERE ((cs.status)::text = 'scheduled'::text)) AS scheduled_sessions,
            count(*) FILTER (WHERE ((cs.status)::text = 'cancelled'::text)) AS cancelled_sessions
           FROM public.class_sessions cs
          WHERE ((cs.course_id)::text = (c.id)::text)) sp ON (true))
     LEFT JOIN LATERAL ( SELECT sum(ts.actual_minutes) AS taught_minutes
           FROM (public.teaching_sessions ts
             JOIN public.class_sessions cs ON (((cs.id)::text = (ts.session_id)::text)))
          WHERE ((cs.course_id)::text = (c.id)::text)) tm ON (true));

--
-- Name: mv_course_dashboard; Type: MATERIALIZED VIEW; Schema: public; Owner: -
--

CREATE MATERIALIZED VIEW public.mv_course_dashboard AS
 SELECT vp.course_id,
    vp.code,
    vp.title,
    vp.total_classes,
    vp.total_available_minutes,
    vp.total_topics,
    vp.completed_topics,
    vp.in_progress_topics,
    vp.topic_completion_pct,
    vp.completed_sessions,
    vp.scheduled_sessions,
    vp.cancelled_sessions,
    vp.session_completion_pct,
    vp.taught_minutes,
    vp.remaining_minutes,
    cm.strong_concepts,
    cm.moderate_concepts,
    cm.weak_concepts,
    cm.bottleneck_concepts,
    cm.not_assessed_concepts,
    tp.remaining_topics,
    tp.remaining_periods,
    tp.pressure_ratio,
    tp.pressure_status,
    timezone('utc'::text, now()) AS refreshed_at
   FROM ((public.v_course_progress vp
     LEFT JOIN LATERAL ( SELECT count(*) FILTER (WHERE (m.mastery_status = 'strong'::text)) AS strong_concepts,
            count(*) FILTER (WHERE (m.mastery_status = 'moderate'::text)) AS moderate_concepts,
            count(*) FILTER (WHERE (m.mastery_status = 'weak'::text)) AS weak_concepts,
            count(*) FILTER (WHERE (m.mastery_status = 'bottleneck'::text)) AS bottleneck_concepts,
            count(*) FILTER (WHERE (m.mastery_status = 'not_assessed'::text)) AS not_assessed_concepts
           FROM public.v_concept_mastery m
          WHERE ((m.course_id)::text = (vp.course_id)::text)) cm ON (true))
     LEFT JOIN LATERAL public.fn_time_pressure(vp.course_id) tp(remaining_topics, remaining_periods, remaining_required_minutes, remaining_available_minutes, pressure_ratio, pressure_status) ON (true))
  WITH NO DATA;

--
-- Name: question_concepts; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.question_concepts (
    question_id character varying(36) NOT NULL,
    concept_id character varying(36) NOT NULL,
    weightage double precision,
    CONSTRAINT check_positive_weightage CHECK ((weightage > (0)::double precision))
);

--
-- Name: questions; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.questions (
    id character varying(36) NOT NULL,
    assessment_id character varying(36) NOT NULL,
    question_number integer NOT NULL,
    max_marks double precision NOT NULL,
    text text NOT NULL,
    CONSTRAINT check_positive_question_marks CHECK ((max_marks > (0)::double precision)),
    CONSTRAINT check_positive_question_number CHECK ((question_number >= 1))
);

--
-- Name: sections; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.sections (
    id character varying(36) NOT NULL,
    course_id character varying(36) NOT NULL,
