);

--
-- Name: users; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.users (
    id character varying(36) NOT NULL,
    email character varying(255) NOT NULL,
    hashed_password character varying(255) NOT NULL,
    full_name character varying(255) NOT NULL,
    role character varying(50) NOT NULL,
    is_active boolean,
    created_at timestamp without time zone,
    CONSTRAINT check_user_role CHECK (((role)::text = ANY ((ARRAY['teacher'::character varying, 'admin'::character varying])::text[])))
);

--
-- Name: v_teaching_history; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_teaching_history WITH (security_invoker='true') AS
 SELECT cs.course_id,
    cs.session_number,
    cs.scheduled_date,
    t.title AS topic_title,
    tm.name AS method_name,
    tm.category AS method_category,
    ts.actual_minutes,
    ts.student_engagement_rating,
    ts.completion_rate,
    ts.teacher_notes,
    ts.conducted_at
   FROM (((public.teaching_sessions ts
     JOIN public.class_sessions cs ON (((cs.id)::text = (ts.session_id)::text)))
     LEFT JOIN public.topics t ON (((t.id)::text = (cs.current_topic_id)::text)))
     LEFT JOIN public.teaching_methods tm ON (((tm.id)::text = (ts.method_id)::text)));

